@Override
public void doPost(HttpServletRequest request, HttpServletResponse response)
        throws ServletException, IOException {
    response.setContentType("text/html;charset=UTF-8");

    String param = "";
    if (request.getHeader("BenchmarkTest01911") != null) {
        param = request.getHeader("BenchmarkTest01911");
    }

    // URL Decode the header value since req.getHeader() doesn't. Unlike req.getParameter().
    param = java.net.URLDecoder.decode(param, "UTF-8");

    String bar = doSomething(request, param);

    java.security.Provider[] provider = java.security.Security.getProviders();
    java.security.MessageDigest md;

    try {
        if (provider.length > 1) {

            md = java.security.MessageDigest.getInstance("SHA-256", provider[0]);
        } else {
            md = java.security.MessageDigest.getInstance("SHA-256", "SUN");
        }
        byte[] input = {(byte) '?'};
        Object inputParam = bar;
        if (inputParam instanceof String) input = ((String) inputParam).getBytes();
        if (inputParam instanceof java.io.InputStream) {
            byte[] strInput = new byte[1000];
            int i = ((java.io.InputStream) inputParam).read(strInput);
            if (i == -1) {
                response.getWriter()
                        .println(
                                "This input source requires a POST, not a GET. Incompatible UI for the InputStream source.");
                return;
            }
            input = java.util.Arrays.copyOf(strInput, i);
        }
        md.update(input);

        byte[] result = md.digest();
        java.io.File fileTarget =
                new java.io.File(
                        new java.io.File(org.owasp.benchmark.helpers.Utils.TESTFILES_DIR),
                        "passwordFile.txt");
        java.io.FileWriter fw =
                new java.io.FileWriter(fileTarget, true); // the true will append the new data
        fw.write(
                "hash_value="
                        + org.owasp.esapi.ESAPI.encoder().encodeForBase64(result, true)
                        + "\n");
        fw.close();
        response.getWriter()
                .println(
                        "Sensitive value '"
                                + org.owasp
                                        .esapi
                                        .ESAPI
                                        .encoder()
                                        .encodeForHTML(new String(input))
                                + "' hashed and stored<br/>");

    } catch (java.security.NoSuchAlgorithmException e) {
        System.out.println(
                "Problem executing hash - TestCase java.security.MessageDigest.getInstance(java.lang.String,java.security.Provider)");
        throw new ServletException(e);
    } catch (java.security.NoSuchProviderException e) {
        System.out.println(
                "Problem executing hash - TestCase java.security.MessageDigest.getInstance(java.lang.String,java.security.Provider)");
        throw new ServletException(e);
    }

    response.getWriter()
            .println(
                    "Hash Test java.security.MessageDigest.getInstance(java.lang.String,java.security.Provider) executed");
} // end doPost
